def find_duplicate_pairs(records):
    # Group row indices by normalized name in a single pass (O(n)), then emit
    # every within-group pair. Avoids the old O(n^2) all-pairs comparison.
    groups = {}
    for i, rec in enumerate(records):
        name = rec["name"].strip().lower()
        groups.setdefault(name, []).append(i)

    pairs = []
    for indices in groups.values():
        for a in range(len(indices)):
            for b in range(a + 1, len(indices)):
                pairs.append((indices[a], indices[b]))

    # Preserve the original ordering (by first index, then second).
    pairs.sort()
    return pairs
